package de.ungarnet.stonechests;

import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.*; import org.bukkit.block.Block; import org.bukkit.block.TileState; import org.bukkit.entity.*; import org.bukkit.event.*; import org.bukkit.event.block.*; import org.bukkit.event.inventory.*; import org.bukkit.event.player.*; import org.bukkit.event.world.ChunkLoadEvent; import org.bukkit.inventory.*; import org.bukkit.inventory.meta.ItemMeta; import org.bukkit.persistence.PersistentDataType; import org.bukkit.plugin.java.JavaPlugin; import org.bukkit.scheduler.BukkitTask;
import java.io.File; import java.sql.SQLException; import java.util.*;

/** The active Bukkit inventory is authoritative; durable page snapshots run after Bukkit actions. */
public final class StoneChests extends JavaPlugin implements Listener {
  private NamespacedKey itemKey,blockKey,hologramKey,navigatorKey; private Database db;
  private final Map<UUID,StoredChest> chests=new HashMap<>(); private final Map<UUID,ChestSession> sessions=new HashMap<>(); private final Map<UUID,UUID> locks=new HashMap<>(); private final Map<UUID,BukkitTask> hologramTasks=new HashMap<>(); private HologramCleanupService hologramCleanup; private static final int NAV_SLOT=8;
  private enum State { CHEST,NAV,SWITCHING,CLOSED }
  private final class ChestSession { final UUID player,chest; final ItemStack previousNav; Inventory inventory; int page; State state=State.CHEST; BukkitTask queued; boolean navigationQueued; ChestSession(Player p,StoredChest c,int page){player=p.getUniqueId();chest=c.id;this.page=page;previousNav=p.getInventory().getItem(NAV_SLOT);} }
  private record ChestHolder(UUID chest,int page) implements InventoryHolder {public Inventory getInventory(){return null;}}
  private record NavHolder(UUID chest) implements InventoryHolder {public Inventory getInventory(){return null;}}

  @Override public void onEnable(){saveDefaultConfig();itemKey=new NamespacedKey(this,"type");blockKey=new NamespacedKey(this,"chest-id");hologramKey=new NamespacedKey(this,"hologram-id");navigatorKey=new NamespacedKey(this,"navigation_compass");try{db=new Database(new File(getDataFolder(),"stonechests.db"));for(StoredChest c:db.load())chests.put(c.id,c);}catch(Exception e){getLogger().severe("SQLite startup failed: "+e.getMessage());getServer().getPluginManager().disablePlugin(this);return;}getServer().getPluginManager().registerEvents(this,this);Objects.requireNonNull(getCommand("stonechests")).setExecutor((s,c,l,a)->command(s,a));registerRecipes();hologramCleanup=new HologramCleanupService(this);hologramCleanup.start();getLogger().info("StoneChests enabled; "+chests.size()+" persistent chests.");}
  @Override public void onDisable(){if(hologramCleanup!=null)hologramCleanup.stop();for(UUID p:new ArrayList<>(sessions.keySet()))end(p,true);for(StoredChest c:chests.values())save(c);if(db!=null)try{db.close();}catch(SQLException ignored){}}
  private boolean command(org.bukkit.command.CommandSender s,String[] a){if(a.length>0&&a[0].equalsIgnoreCase("reload")){if(!s.hasPermission("stonechests.reload")){s.sendMessage("No permission.");return true;}reloadConfig();registerRecipes();s.sendMessage("StoneChests reloaded.");return true;}if(a.length>0&&a[0].equalsIgnoreCase("info")){s.sendMessage("StoneChests: "+chests.size()+" persistent chests, SQLite active.");return true;}s.sendMessage("Use the compass in hotbar slot 9 while a StoneChest is open.");return true;}
  ItemStack item(ChestType t){ItemStack i=new ItemStack(Material.CHEST);ItemMeta m=i.getItemMeta();m.displayName(Component.text("◆ "+t.title,t.color));m.lore(List.of(Component.text(t.defaultPages*54+" Slots",t.color)));m.getPersistentDataContainer().set(itemKey,PersistentDataType.STRING,t.name());i.setItemMeta(m);return i;}
  private ItemStack navItem(){ItemStack i=new ItemStack(Material.COMPASS);ItemMeta m=i.getItemMeta();m.displayName(Component.text("StoneChest navigation",NamedTextColor.GOLD));m.lore(List.of(Component.text("Click to change page")));m.getPersistentDataContainer().set(navigatorKey,PersistentDataType.BYTE,(byte)1);i.setItemMeta(m);return i;}
  private boolean isNavigator(ItemStack item){return item!=null&&item.hasItemMeta()&&item.getItemMeta().getPersistentDataContainer().has(navigatorKey,PersistentDataType.BYTE);}
  private void registerRecipes(){for(ChestType t:ChestType.values()){NamespacedKey k=new NamespacedKey(this,"craft_"+t.key());getServer().removeRecipe(k);if(!getConfig().getBoolean("recipes."+t.key()+".enabled",true))continue;ShapedRecipe r=new ShapedRecipe(k,item(t));r.shape("AAA","ABA","AAA");r.setIngredient('A',t.recipeMaterial);if(t==ChestType.STONE)r.setIngredient('B',Material.CHEST);else r.setIngredient('B',new RecipeChoice.ExactChoice(item(t==ChestType.IRON?ChestType.STONE:ChestType.IRON)));getServer().addRecipe(r);}}
  private int pages(ChestType t){return Math.max(t.defaultPages,getConfig().getInt("chests."+t.key()+".pages",t.defaultPages));}
  @EventHandler public void place(BlockPlaceEvent e){String raw=e.getItemInHand().hasItemMeta()?e.getItemInHand().getItemMeta().getPersistentDataContainer().get(itemKey,PersistentDataType.STRING):null;if(raw==null)return;try{ChestType t=ChestType.valueOf(raw);if(!getConfig().getBoolean("chests."+t.key()+".enabled",true)){e.setCancelled(true);return;}StoredChest c=new StoredChest(UUID.randomUUID(),t,e.getBlockPlaced().getLocation(),pages(t));TileState state=(TileState)e.getBlockPlaced().getState();state.getPersistentDataContainer().set(blockKey,PersistentDataType.STRING,c.id.toString());state.update();chests.put(c.id,c);save(c);ensureHologram(c);}catch(IllegalArgumentException x){e.setCancelled(true);}}
  @EventHandler(ignoreCancelled=true) public void interact(PlayerInteractEvent e){if(e.getAction()!=Action.RIGHT_CLICK_BLOCK||e.getClickedBlock()==null)return;StoredChest c=find(e.getClickedBlock());if(c==null)return;e.setCancelled(true);Player p=e.getPlayer();if(!p.hasPermission("stonechests.use")){p.sendMessage("No permission.");return;}UUID owner=locks.get(c.id);if(owner!=null&&!owner.equals(p.getUniqueId())){p.sendMessage("This StoneChest is currently in use.");return;}start(p,c,0);}
  @EventHandler(ignoreCancelled=true) public void breakChest(BlockBreakEvent e){StoredChest c=find(e.getBlock());if(c==null)return;e.setCancelled(true);if(locks.containsKey(c.id)){e.getPlayer().sendMessage("Chest is open.");return;}World w=e.getBlock().getWorld();e.getBlock().setType(Material.AIR,false);w.dropItemNaturally(c.location,item(c.type));for(ItemStack[] page:c.pages)for(ItemStack i:page)if(i!=null&&!i.getType().isAir())w.dropItemNaturally(c.location,i);removeHologram(c);chests.remove(c.id);try{db.delete(c.id);}catch(SQLException x){getLogger().severe("Could not delete chest "+c.id+": "+x.getMessage());}}
  private void start(Player p,StoredChest c,int page){ChestSession old=sessions.get(p.getUniqueId());if(old!=null)end(p.getUniqueId(),true);removeMarkedNavigators(p,-1);ChestSession s=new ChestSession(p,c,Math.floorMod(page,c.pages.length));sessions.put(s.player,s);locks.put(c.id,s.player);p.getInventory().setItem(NAV_SLOT,navItem());openPage(p,s);}
  private void openPage(Player p,ChestSession s){StoredChest c=chests.get(s.chest);if(c==null){debug("Navigation failed: chest missing for "+s.player);return;}Inventory inv=Bukkit.createInventory(new ChestHolder(c.id,s.page),54,Component.text(c.type.title+" — Seite "+(s.page+1)+"/"+c.pages.length,c.type.color));for(int n=0;n<54;n++)inv.setItem(n,c.pages[s.page][n]);/* Set the new reference before openInventory closes the old view. */s.state=State.SWITCHING;s.inventory=inv;p.openInventory(inv);s.state=State.CHEST;}
  private void openNav(Player p,ChestSession s){flush(s);StoredChest c=chests.get(s.chest);s.state=State.NAV;Inventory inv=Bukkit.createInventory(new NavHolder(c.id),9,Component.text("StoneChest navigation"));inv.setItem(2,button(Material.ARROW,"Previous page"));inv.setItem(4,button(Material.PAPER,"Page "+(s.page+1)+" of "+c.pages.length));inv.setItem(6,button(Material.ARROW,"Next page"));inv.setItem(8,button(Material.CHEST,"Back to chest"));p.openInventory(inv);}
  private ItemStack button(Material m,String name){ItemStack i=new ItemStack(m);ItemMeta x=i.getItemMeta();x.displayName(Component.text(name));i.setItemMeta(x);return i;}
  @EventHandler public void click(InventoryClickEvent e){Player p=(Player)e.getWhoClicked();ChestSession s=sessions.get(p.getUniqueId());if(s==null)return;if(e.getView().getTopInventory().getHolder() instanceof NavHolder h){e.setCancelled(true);if(!h.chest.equals(s.chest)||e.getRawSlot()<0||e.getRawSlot()>8)return;if(e.getRawSlot()==2){s.page=Math.max(0,s.page-1);openPage(p,s);}else if(e.getRawSlot()==6){s.page=Math.min(chests.get(s.chest).pages.length-1,s.page+1);openPage(p,s);}else if(e.getRawSlot()==4||e.getRawSlot()==8)openPage(p,s);return;}if(!(e.getView().getTopInventory().getHolder() instanceof ChestHolder h)||!h.chest.equals(s.chest)||s.state!=State.CHEST)return;boolean navClicked=e.getClickedInventory()==e.getView().getBottomInventory()&&e.getSlot()==NAV_SLOT&&isNavigator(e.getCurrentItem());boolean navHotbar=e.getClick()==ClickType.NUMBER_KEY&&e.getHotbarButton()==NAV_SLOT&&isNavigator(p.getInventory().getItem(NAV_SLOT));boolean navInvolved=isNavigator(e.getCurrentItem())||isNavigator(e.getCursor())||navHotbar;if(navClicked){e.setCancelled(true);queueCompassNavigation(p,s,e.isRightClick()?-1:1);return;}if(navInvolved){e.setCancelled(true);return;}Bukkit.getScheduler().runTask(this,()->schedule(s));}
  @EventHandler public void drag(InventoryDragEvent e){ChestSession s=sessions.get(e.getWhoClicked().getUniqueId());if(s==null)return;int navRaw=e.getView().getTopInventory().getSize()+27+NAV_SLOT;if(e.getRawSlots().contains(navRaw)||isNavigator(e.getOldCursor())||e.getView().getTopInventory().getHolder() instanceof NavHolder){e.setCancelled(true);return;}if(e.getView().getTopInventory().getHolder() instanceof ChestHolder)Bukkit.getScheduler().runTask(this,()->schedule(s));}
  @EventHandler public void close(InventoryCloseEvent e){ChestSession s=sessions.get(e.getPlayer().getUniqueId());if(s==null)return;if(e.getInventory()==s.inventory&&s.state==State.CHEST){flush(s);end(s.player,false);}else if(e.getInventory().getHolder() instanceof NavHolder&&s.state==State.NAV)end(s.player,false);}
  @EventHandler public void quit(PlayerQuitEvent e){end(e.getPlayer().getUniqueId(),true);}
  @EventHandler public void dropNavigator(PlayerDropItemEvent e){if(isNavigator(e.getItemDrop().getItemStack()))e.setCancelled(true);}
  @EventHandler public void swapHands(PlayerSwapHandItemsEvent e){if(isNavigator(e.getMainHandItem())||isNavigator(e.getOffHandItem()))e.setCancelled(true);}
  @EventHandler public void heldSlot(PlayerItemHeldEvent e){ChestSession s=sessions.get(e.getPlayer().getUniqueId());if(s!=null&&e.getNewSlot()==NAV_SLOT&&!isNavigator(e.getPlayer().getInventory().getItem(NAV_SLOT))){e.setCancelled(true);}}
  @EventHandler public void playerJoin(PlayerJoinEvent e){if(!sessions.containsKey(e.getPlayer().getUniqueId()))removeMarkedNavigators(e.getPlayer(),-1);}
  private void schedule(ChestSession s){if(s.state!=State.CHEST||s.queued!=null)return;s.queued=Bukkit.getScheduler().runTaskLater(this,()->{s.queued=null;flush(s);},1);}
  /** InventoryClickEvent is still mutating its view; perform the page hand-off exactly once next tick. */
  private void queueCompassNavigation(Player player,ChestSession session,int direction){
    if(session.navigationQueued){debug("Navigation ignored: already queued for "+player.getUniqueId());return;}
    session.navigationQueued=true;
    Bukkit.getScheduler().runTask(this,()->{
      session.navigationQueued=false;
      ChestSession active=sessions.get(player.getUniqueId());
      StoredChest chest=chests.get(session.chest);
      if(active!=session||chest==null||session.state!=State.CHEST){debug("Navigation failed: invalid session player="+player.getUniqueId()+" chest="+session.chest);return;}
      int target=session.page+direction;
      debug("Navigation player="+player.getUniqueId()+" chest="+session.chest+" current="+session.page+" target="+target+" pages="+chest.pages.length);
      if(target<0||target>=chest.pages.length){debug("Navigation rejected: target outside page range");return;}
      flush(session);
      session.page=target;
      openPage(player,session);
      queueHologram(chest);
      debug("Navigation opened target="+target+" for player="+player.getUniqueId());
    });
  }
  private void debug(String message){if(getConfig().getBoolean("debug",false))getLogger().info("[debug] "+message);}
  /** The only mutation path from a displayed page to durable chest state, after Bukkit finished the action. */
  private void flush(ChestSession s){if(s.queued!=null){s.queued.cancel();s.queued=null;}if(s.state!=State.CHEST||s.inventory==null)return;StoredChest c=chests.get(s.chest);if(c==null)return;for(int n=0;n<54;n++){ItemStack i=s.inventory.getItem(n);c.pages[s.page][n]=i==null?null:i.clone();}save(c);queueHologram(c);}
  private void end(UUID player,boolean close){ChestSession s=sessions.remove(player);if(s==null)return;flush(s);s.state=State.CLOSED;locks.remove(s.chest,player);Player p=Bukkit.getPlayer(player);if(p!=null){removeMarkedNavigators(p,-1);p.getInventory().setItem(NAV_SLOT,s.previousNav);if(close)p.closeInventory();}}
  private void removeMarkedNavigators(Player p,int exemptSlot){ItemStack[] contents=p.getInventory().getContents();for(int slot=0;slot<contents.length;slot++)if(slot!=exemptSlot&&isNavigator(contents[slot]))p.getInventory().setItem(slot,null);if(isNavigator(p.getInventory().getItemInOffHand()))p.getInventory().setItemInOffHand(null);}
  @EventHandler public void automation(InventoryMoveItemEvent e){if(getConfig().getBoolean("automation-blocking",true)&&(find(e.getSource().getLocation().getBlock())!=null||find(e.getDestination().getLocation().getBlock())!=null))e.setCancelled(true);}
  @EventHandler public void piston(BlockPistonExtendEvent e){if(e.getBlocks().stream().anyMatch(b->find(b)!=null))e.setCancelled(true);}
  @EventHandler public void chunkLoad(ChunkLoadEvent e){for(StoredChest c:chests.values())if(c.location.getChunk().equals(e.getChunk()))ensureHologram(c);}
  private StoredChest find(Block b){if(!(b.getState() instanceof TileState t))return null;String id=t.getPersistentDataContainer().get(blockKey,PersistentDataType.STRING);try{return id==null?null:chests.get(UUID.fromString(id));}catch(IllegalArgumentException e){return null;}}
  NamespacedKey hologramKey(){return hologramKey;}
  StoredChest chest(UUID id){return chests.get(id);}
  Collection<StoredChest> allChests(){return Collections.unmodifiableCollection(chests.values());}
  boolean validChestBlock(StoredChest chest){World world=chest.location.getWorld();return world!=null&&world.isChunkLoaded(chest.location.getBlockX()>>4,chest.location.getBlockZ()>>4)&&find(chest.location.getBlock())==chest;}
  void adoptHologram(StoredChest chest,TextDisplay display){if(!display.getUniqueId().equals(chest.hologram)){chest.hologram=display.getUniqueId();save(chest);}}
  void ensureHologramForCleanup(StoredChest chest){ensureHologram(chest);}
  private void save(StoredChest c){try{db.save(c);}catch(SQLException e){getLogger().severe("Database save failed for "+c.id+": "+e.getMessage());}}
  private void queueHologram(StoredChest c){if(!getConfig().getBoolean("holograms.enabled",true))return;BukkitTask old=hologramTasks.remove(c.id);if(old!=null)old.cancel();hologramTasks.put(c.id,Bukkit.getScheduler().runTaskLater(this,()->ensureHologram(c),20));}
  private void ensureHologram(StoredChest c){if(!getConfig().getBoolean("holograms.enabled",true))return;TextDisplay d=null;if(c.hologram!=null&&Bukkit.getEntity(c.hologram) instanceof TextDisplay x)d=x;if(d==null){d=(TextDisplay)c.location.getWorld().spawnEntity(c.location.clone().add(.5,getConfig().getDouble("holograms.height",1.75),.5),EntityType.TEXT_DISPLAY);c.hologram=d.getUniqueId();d.getPersistentDataContainer().set(hologramKey,PersistentDataType.STRING,c.id.toString());d.setBillboard(Display.Billboard.CENTER);d.setShadowed(true);d.setSeeThrough(false);}d.text(Component.text("◆ "+c.type.title.toUpperCase()+"\n"+c.usedSlots()+" / "+(c.pages.length*54)+" SLOTS",c.type.color));save(c);}
  private void removeHologram(StoredChest c){if(c.hologram!=null&&Bukkit.getEntity(c.hologram)!=null)Bukkit.getEntity(c.hologram).remove();c.hologram=null;}
}
